"""Plot the CSV outputs generated by evaluate_baselines/evaluate_training.

Run after evaluation: python -m rl.plot_evaluation
Figures are written to results/evaluation_plots/. These are SIMULATED data.
The retention-vs-day plot is an EVALUATION trajectory, not QWI's training
learning curve; training return vs training transitions is shown separately.
"""
from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

from config import ROOT
from rl.evaluation_metrics import mean_ci95

OUT = Path(ROOT) / 'results'
FIG = OUT / 'evaluation_plots'


def draw():
    FIG.mkdir(parents=True, exist_ok=True)
    paths = []
    traj_file = OUT / 'evaluation_retention_trajectories.csv'
    summary_file = OUT / 'evaluation_summary.csv'
    if not traj_file.exists() or not summary_file.exists():
        raise FileNotFoundError('Run python -m rl.evaluate_baselines first')
    traj = pd.read_csv(traj_file)
    summ = pd.read_csv(summary_file)
    for world, g in traj.groupby('world'):
        fig, ax = plt.subplots(figsize=(9, 5))
        keep = ['QWI (online speed)', 'Forgetting risk (online)',
                'SM-2-style', 'Most overdue', 'Random']
        for name in keep:
            rows = g[g.policy == name]
            if rows.empty:
                continue
            tuples = [(int(day), mean_ci95(x.mean_recall_before_review))
                      for day, x in rows.groupby('day')]
            days = np.array([p[0] for p in tuples])
            means = np.array([p[1][0] for p in tuples])
            low = np.array([p[1][2] for p in tuples])
            high = np.array([p[1][3] for p in tuples])
            ax.plot(days, means, label=name)
            if np.isfinite(low).all():
                ax.fill_between(days, low, high, alpha=.14)
        ax.set(xlabel='Evaluation day (NOT training steps)',
               ylabel='Mean model-derived recall before review',
               title=f'Simulated retention trajectories — {world} world')
        ax.set_ylim(0, 1)
        ax.legend(fontsize=8)
        fig.tight_layout()
        dst = FIG / f'retention_trajectory_{world}.png'
        fig.savefig(dst, dpi=170)
        paths.append(dst)
        plt.close(fig)
    for world, frame in summ.groupby('world'):
        frame = frame[frame.diagnostic_oracle == 0].copy()
        fig, ax = plt.subplots(figsize=(10, 5))
        ax.barh(frame.policy, frame.mean_final_ARP)
        ax.set(xlim=(0, 1), xlabel='Final average recall probability (ARP)',
               title=f'Final simulated retention — {world} world')
        fig.tight_layout()
        dst = FIG / f'final_ARP_{world}.png'
        fig.savefig(dst, dpi=170)
        paths.append(dst)
        plt.close(fig)
    training_file = OUT / 'training_learning_curve.csv'
    if training_file.exists():
        train = pd.read_csv(training_file).sort_values('steps_per_bucket')
        fig, ax = plt.subplots(figsize=(8, 5))
        x = train.steps_per_bucket.to_numpy()
        ax.plot(x, train.mean_eval_episodic_return.to_numpy(), marker='o',
                label='QWI trained across independent training seeds')
        lo, hi = train.return_ci_low.to_numpy(), train.return_ci_high.to_numpy()
        if np.isfinite(lo).all():
            ax.fill_between(x, lo, hi, alpha=.2, label='95% t-CI across training seeds')
        ax.set(xlabel='Training transitions per half-life bucket',
               ylabel='Mean evaluation episodic return',
               title='QWI sample efficiency (simulated training)')
        ax.legend(fontsize=8)
        fig.tight_layout()
        dst = FIG / 'training_return_vs_steps.png'
        fig.savefig(dst, dpi=170)
        paths.append(dst)
        plt.close(fig)
    for dst in paths:
        print(dst)


if __name__ == '__main__':
    draw()
